import {mediaSearchClient} from './media-search-client.js';
import {normalizeReferenceMediaState,mediaAttributionText} from './media-search-protocol.js';
import {createOperationStatus,nextPaint} from './operation-status.js';
const node=(tag,className='',text)=>{const el=document.createElement(tag);el.className=className;if(text!==undefined)el.textContent=text;return el;};
const button=(id,text,kind='outline')=>{const el=node('button',kind,text);el.type='button';el.id=id;return el;};
function sourceLink(text,url){const el=node('a','',text);el.href=url;el.target='_blank';el.rel='noopener noreferrer';return el;}
const scope=api=>({projectId:api.getProject().id,workspaceId:api.getWorkspaceId?.()??null});
const owns=(api,target)=>target?.projectId===api.getProject().id&&(target.workspaceId??null)===(api.getWorkspaceId?.()??null);
const scopeKey=target=>JSON.stringify([target.projectId,target.workspaceId]);
function includeStyle(){if(document.getElementById('referenceMediaStyles'))return;const style=node('link');style.id='referenceMediaStyles';style.rel='stylesheet';style.href=new URL('./reference-media.css',import.meta.url).href;document.head.append(style);}
async function copy(value){if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(value);return;}const field=node('textarea');field.value=value;document.body.append(field);field.select();const ok=document.execCommand('copy');field.remove();if(!ok)throw new Error('복사하지 못했어요. 출처 링크를 직접 열어 확인해 주세요.');}

/** Actual, reviewable public image sources; only explicitly chosen files become references. */
export function setupReferenceMedia(api){
 const topic=document.getElementById('researchTopic'),topicCard=topic?.closest('.script-topic-card'),dialog=document.getElementById('scriptStudioDialog');if(!topicCard||!dialog)throw new Error('이미지 자료 검색 위치를 찾지 못했어요.');includeStyle();
 const client=api.mediaSearchClient||mediaSearchClient;
 const alongside=node('label','reference-media-option'),enabled=node('input');enabled.type='checkbox';enabled.id='researchImagesWithTopic';enabled.checked=true;alongside.append(enabled,document.createTextNode('자료를 찾을 때 이미지 자료도 함께 찾기'));topicCard.append(alongside);
 const quick=button('findReferenceImagesBtn','이미지 자료 찾기');topicCard.querySelector('.script-generation-controls')?.append(quick);
 const section=node('details','reference-media-section');section.id='referenceMediaSection';const heading=node('summary','','이미지 참고 자료 · 직접 보고 선택');section.append(heading);
 const body=node('div','reference-media-body'),help=node('p','script-studio-help','Wikimedia Commons의 실제 이미지 자료를 찾아요. 결과의 출처·저작자·이용 조건을 보고 고른 뒤 레퍼런스로 가져오세요. AI 이미지 생성은 실행하지 않아요.');body.append(help);
 const label=node('label','reference-media-query');label.htmlFor='referenceImageQuery';label.append(node('span','','이미지 검색어'));const query=node('input');query.id='referenceImageQuery';query.maxLength=500;query.placeholder='주제 또는 이미지에 나타날 대상을 입력하세요';label.append(query);body.append(label);
 const actions=node('div','reference-media-actions'),search=button('searchReferenceImagesBtn','이미지 검색'),cancel=button('cancelReferenceImagesBtn','검색 취소','ghost');cancel.hidden=true;actions.append(search,cancel);body.append(actions);
 const operation=createOperationStatus({container:body,region:section,id:'referenceMediaOperation'}),status=node('p','reference-media-status');status.id='referenceMediaStatus';status.setAttribute('role','status');const error=node('p','reference-media-error');error.id='referenceMediaError';error.setAttribute('role','alert');body.append(status,error);
 const gallery=node('div','reference-media-grid');gallery.id='referenceImageResults';body.append(gallery);
 const imports=node('div','reference-media-actions'),apply=button('applyReferenceImagesBtn','선택 이미지를 고정 레퍼런스에 추가','primary'),addScenes=button('addReferenceImagesToScenesBtn','선택 이미지를 장면으로 가져오기'),copyCredit=button('copyReferenceImageCreditsBtn','선택 자료 출처 복사');imports.append(apply,addScenes,copyCredit);body.append(imports);
 const credits=node('details','reference-media-credits');credits.append(node('summary','','가져온 이미지 출처'));const creditList=node('div');creditList.id='referenceImportedCredits';credits.append(creditList);body.append(credits);section.append(body);topicCard.after(section);
 let owner='',fingerprint='',galleryKey='',creditsKey='',busy='',controller=null,sequence=0,saving=false,requestId='',disposed=false;
 const current=()=>normalizeReferenceMediaState(api.getProject().production?.referenceMedia||{});
 function mutate(action){saving=true;try{(api.mutateProductionMetadata||api.mutate)(project=>{project.production||={version:1};const value=normalizeReferenceMediaState(project.production.referenceMedia||{});action(value);project.production.referenceMedia=normalizeReferenceMediaState(value);});}finally{saving=false;}render();}
 function canEdit(){return !busy&&(!api.canMutate||api.canMutate());}
 function refresh(){const state=current(),selected=state.results.filter(item=>state.selectedIds.includes(item.id)),available=5-(api.getProject().imageStudio?.references?.length||0);query.disabled=enabled.disabled=search.disabled=quick.disabled=!canEdit();apply.disabled=!canEdit()||!selected.length||selected.length>available;addScenes.disabled=!canEdit()||!selected.length||(api.getProject().scenes?.length||0)+selected.length>200;copyCredit.disabled=Boolean(busy)||!selected.length;cancel.hidden=!busy;cancel.textContent=busy==='apply'?'가져오기 취소':'검색 취소';for(const input of gallery.querySelectorAll('input[type=checkbox]'))input.disabled=!canEdit();
  if(!busy)status.textContent=state.results.length?`이미지 ${state.results.length}개 · ${selected.length}개 선택 · 레퍼런스에 ${Math.max(0,available)}개 더 넣을 수 있어요.`:state.searchedAt?'검색 결과가 없어요. 검색어를 더 넓게 쓰거나 영문 키워드를 함께 사용해 보세요.':'이미지를 검색한 뒤 필요한 자료만 선택하세요.';
 }
 function stop(message='이미지 자료 찾기를 취소했어요. 기존 검색 결과와 레퍼런스는 유지돼요.'){sequence++;controller?.abort();controller=null;if(busy)operation.cancel(message);busy='';refresh();}
 function draw(state){const next=JSON.stringify(state.results);if(next!==galleryKey){galleryKey=next;gallery.replaceChildren();for(const item of state.results){const card=node('article','reference-media-card'),choice=node('label','reference-media-choice'),check=node('input');check.type='checkbox';check.value=item.id;check.dataset.mediaId=item.id;check.setAttribute('aria-label',`${item.title} 선택`);choice.append(check,node('strong','',item.title));const image=node('img');image.crossOrigin='anonymous';image.src=item.previewUrl||item.mediaUrl;image.alt=item.title;image.loading='lazy';image.referrerPolicy='no-referrer';image.addEventListener('error',()=>{image.hidden=true;card.querySelector('.reference-media-preview-note').textContent='미리보기를 불러오지 못했어요. 출처에서 자료를 확인할 수 있어요.';});const note=node('p','reference-media-preview-note');const description=node('p','reference-media-description',item.description),meta=node('p','reference-media-meta',[item.artist?`저작자: ${item.artist}`:'저작자 정보는 출처에서 확인',item.license?`Commons 표기: ${item.license}`:'이용 조건은 출처에서 확인'].join(' · '));const links=node('div','reference-media-links');links.append(sourceLink('원본·출처 보기',item.sourceUrl));if(item.licenseUrl)links.append(sourceLink('이용 조건',item.licenseUrl));card.append(image,note,choice,description,meta,links);gallery.append(card);check.addEventListener('change',()=>{try{mutate(value=>{value.selectedIds=check.checked?[...value.selectedIds,item.id]:value.selectedIds.filter(id=>id!==item.id);});}catch(cause){error.textContent=cause.message;}});}}
  for(const check of gallery.querySelectorAll('input[type=checkbox]'))check.checked=state.selectedIds.includes(check.value);
  const saved=JSON.stringify(state.imports);if(saved!==creditsKey){creditsKey=saved;creditList.replaceChildren(...state.imports.map(item=>{const row=node('p','reference-media-meta');row.append(sourceLink(item.title,item.sourceUrl),document.createTextNode(` · ${item.artist||'저작자 정보 확인'} · ${item.license||'이용 조건 확인'}`));return row;}));credits.hidden=!state.imports.length;}
 }
 function render(){if(disposed)return;const key=scopeKey(scope(api));if(key!==owner){stop('프로젝트가 바뀌어 이미지 자료 찾기를 중지했어요.');owner=key;fingerprint='';galleryKey='';creditsKey='';requestId='';error.textContent='';operation.clear();}const state=current(),next=JSON.stringify(state);if(!saving&&next!==fingerprint){fingerprint=next;if(document.activeElement!==query&&!busy)query.value=state.query;enabled.checked=state.withTopic;draw(state);}refresh();}
 async function runSearch(value,{fromTopic=false,id=''}={}){if(busy)return;error.textContent='';const text=String(value??query.value).trim();if(!text){error.textContent='찾을 이미지의 주제나 검색어를 입력해 주세요.';return;}const target=scope(api),seq=++sequence;controller=new AbortController();busy='search';requestId=id;section.open=true;query.value=text;status.textContent='실제 이미지 자료와 출처를 찾고 있어요.';const job=operation.start('Wikimedia Commons 이미지 검색 중');refresh();try{await nextPaint();const results=await client.search(text,{kind:'image',signal:controller.signal});if(seq!==sequence||!owns(api,target))return;mutate(state=>{state.query=text;state.results=results;state.selectedIds=[];state.searchedAt=new Date().toISOString();});await api.persist?.();if(seq===sequence&&owns(api,target))job.finish(results.length?`${results.length}개의 실제 이미지 자료를 찾았어요.`:'이미지 자료 검색을 마쳤지만 결과가 없어요.');}catch(cause){if(seq!==sequence||!owns(api,target))return;cause.name==='AbortError'?job.cancel('이미지 검색을 취소했어요.'):(error.textContent=cause.message,job.fail(cause.message));}finally{if(seq===sequence){busy='';controller=null;refresh();}}}
 async function applySelected(destination='reference'){if(busy)return;const toScenes=destination==='scenes';const state=current(),selected=state.results.filter(item=>state.selectedIds.includes(item.id));if(!selected.length)return;const existing=api.getProject().imageStudio?.references||[];if(!toScenes&&existing.length+selected.length>5){error.textContent='고정 레퍼런스는 합계 5장까지 추가할 수 있어요. 기존 이미지를 정리하거나 선택 수를 줄여 주세요.';return;}const ids=new Set([...state.imports,...selected].map(item=>item.id));if(ids.size>50){error.textContent='가져온 자료 출처가 50개를 넘어요. 다른 프로젝트로 나눠 보관해 주세요.';return;}const target=scope(api),seq=++sequence;controller=new AbortController();busy='apply';error.textContent='';const job=operation.start('선택한 실제 이미지 파일을 준비하고 있어요.');refresh();try{const files=[];let total=toScenes?0:existing.reduce((sum,ref)=>sum+(api.getAssets().get(ref.assetId)?.blob?.size||0),0);for(const item of selected){job.update(`${files.length+1} / ${selected.length} · ${item.title}`);const file=await client.download(item,{signal:controller.signal});if(seq!==sequence||!owns(api,target))return;total+=file.size;if(total>(toScenes?100:20)*1024*1024)throw new Error(toScenes?'이미지 자료는 한 번에 합계 100MB까지 가져올 수 있어요. 선택 수를 줄여 주세요.':'레퍼런스는 기존 자료와 합계 20MB까지 추가할 수 있어요. 선택 수를 줄여 주세요.');files.push(file);}if(seq!==sequence||!owns(api,target))return;if(toScenes)await api.addImages(files);else await api.addReferenceImages(files);if(seq!==sequence||!owns(api,target))return;mutate(value=>{const merged=new Map(value.imports.map(item=>[item.id,item]));for(const item of selected)merged.set(item.id,item);value.imports=[...merged.values()];});await api.persist?.();job.finish(`${files.length}장을 ${toScenes?'장면으로 가져왔어요':'고정 레퍼런스로 추가했어요'}. 출처도 프로젝트에 보관했어요.`);api.toast?.(toScenes?'선택한 이미지 자료를 장면으로 가져왔어요.':'선택한 이미지 자료를 고정 레퍼런스에 추가했어요.');}catch(cause){if(seq!==sequence)return;cause.name==='AbortError'?job.cancel('가져오기를 취소했어요.'):(error.textContent=cause.message,job.fail(cause.message));}finally{if(seq===sequence){busy='';controller=null;refresh();}}}
 quick.addEventListener('click',()=>{section.open=true;if(!query.value.trim())query.value=topic.value;runSearch(query.value);});search.addEventListener('click',()=>runSearch(query.value));cancel.addEventListener('click',()=>stop());apply.addEventListener('click',()=>applySelected());addScenes.addEventListener('click',()=>applySelected('scenes'));query.addEventListener('input',()=>{if(busy==='search')stop('검색어가 바뀌어 이전 이미지 검색을 중지했어요.');});enabled.addEventListener('change',()=>{try{mutate(state=>{state.withTopic=enabled.checked;});}catch(cause){error.textContent=cause.message;}});
 copyCredit.addEventListener('click',()=>{const state=current();copy(state.results.filter(item=>state.selectedIds.includes(item.id)).map(mediaAttributionText).join('\n\n')).then(()=>{status.textContent='선택 자료의 출처 표시를 복사했어요.';}).catch(cause=>{error.textContent=cause.message;});});
 const startEvent=event=>{const detail=event.detail;if(!enabled.checked||!owns(api,detail))return;if(busy)stop('새 주제로 이미지 자료를 찾고 있어요.');runSearch(detail.topic,{fromTopic:true,id:detail.requestId});};
 const cancelEvent=event=>{if(event.detail?.requestId&&event.detail.requestId===requestId&&busy==='search')stop();};window.addEventListener('studio-topic-research-start',startEvent);window.addEventListener('studio-topic-research-cancel',cancelEvent);dialog.addEventListener('close',()=>{if(busy)stop();});
 render();return{render,flush(){},reset(){stop('');owner='';render();},onClose(){if(busy)stop();},dispose(){disposed=true;stop('');window.removeEventListener('studio-topic-research-start',startEvent);window.removeEventListener('studio-topic-research-cancel',cancelEvent);section.remove();alongside.remove();quick.remove();operation.dispose();}};
}
